/**
 * 提款编排：报价 → 申请（逐层预占+创建借据+提交付款）→ 结果确认 → 入账（Fineract 放款+逐层实占）。
 * 状态机与异常恢复语义见 docs/接口契约-阶段2.md §6；额度按多层口径校验与记账（接口契约-阶段3.md §1）。
 * 产品规则按报价绑定的版本快照执行（ProductConfigVersion），新配置只适用于新报价。
 */
@Service
public class DrawdownService {

    private static final Logger log = LoggerFactory.getLogger(DrawdownService.class);

    private final DrawdownQuoteRepository quoteRepo;
    private final DrawdownOrderRepository orderRepo;
    private final ProductConfigRepository productRepo;
    private final ProductConfigVersionRepository versionRepo;
    private final LimitService limitService;
    private final FineractClient fineract;
    private final SimulatorClient simulator;
    private final ObjectMapper objectMapper;

    public DrawdownService(DrawdownQuoteRepository quoteRepo, DrawdownOrderRepository orderRepo,
                           ProductConfigRepository productRepo, ProductConfigVersionRepository versionRepo,
                           LimitService limitService, FineractClient fineract, SimulatorClient simulator,
                           ObjectMapper objectMapper) {
        this.quoteRepo = quoteRepo;
        this.orderRepo = orderRepo;
        this.productRepo = productRepo;
        this.versionRepo = versionRepo;
        this.limitService = limitService;
        this.fineract = fineract;
        this.simulator = simulator;
        this.objectMapper = objectMapper;
    }

    // ------------------------------------------------------------------ 报价

    @Transactional
    public Map<String, Object> quote(String creditId, String productId, BigDecimal amount, Integer termMonths,
                                     String repaymentMode, String firstRepaymentDate) {
        ProductConfig product = product(productId);
        validateAmountAndTerm(product, amount, termMonths, repaymentMode);
        limitService.get(creditId); // 授信存在性
        Map<String, Object> trial = fineract.calculateLoanSchedule(product.getFineractProductId(),
                amount, termMonths, repaymentMode, firstRepaymentDate);

        DrawdownQuote quote = new DrawdownQuote();
        quote.setQuoteNo(Ids.next("QT-"));
        quote.setCreditId(creditId);
        quote.setProductId(productId);
        quote.setAmount(amount);
        quote.setTermMonths(termMonths);
        quote.setRepaymentMode(repaymentMode);
        quote.setFirstRepaymentDate(firstRepaymentDate);
        quote.setAnnualInterestRate(product.getAnnualInterestRate());
        quote.setValidUntil(Ids.now().plusMinutes(30));
        quote.setStatus(DrawdownQuote.Status.UNUSED);
        quote.setTrialScheduleJson(writeJson(trial));
        quote.setProductVersionId(resolveVersion(product).getVersionId());
        quoteRepo.save(quote);
        return Map.of("quoteNo", quote.getQuoteNo(),
                "productVersionId", quote.getProductVersionId(),
                "annualInterestRate", product.getAnnualInterestRate(),
                "trialSchedule", trial.get("periods") == null ? List.of() : trial.get("periods"),
                "validUntil", quote.getValidUntil().toString());
    }

    /**
     * 版本快照：产品配置当前字段与最新版本一致则复用，否则生成新版本（不可变）。
     */
    private ProductConfigVersion resolveVersion(ProductConfig product) {
        Optional<ProductConfigVersion> latest = versionRepo.findFirstByProductIdOrderByVersionDesc(product.getProductId());
        if (latest.isPresent() && sameRules(latest.get(), product)) {
            return latest.get();
        }
        ProductConfigVersion version = new ProductConfigVersion();
        version.setVersionId("PV-" + product.getProductId() + "-"
                + (latest.map(v -> v.getVersion() + 1).orElse(1)));
        version.setProductId(product.getProductId());
        version.setVersion(latest.map(v -> v.getVersion() + 1).orElse(1));
        version.setMinAmount(product.getMinAmount());
        version.setMaxAmount(product.getMaxAmount());
        version.setTerms(product.getTerms());
        version.setRepaymentModes(product.getRepaymentModes());
        version.setAnnualInterestRate(product.getAnnualInterestRate());
        version.setRequiresGuarantee(product.isRequiresGuarantee());
        version.setFineractProductId(product.getFineractProductId());
        version.setEffectiveAt(Ids.now());
        return versionRepo.save(version);
    }

    private boolean sameRules(ProductConfigVersion version, ProductConfig product) {
        return version.getMinAmount().compareTo(product.getMinAmount()) == 0
                && version.getMaxAmount().compareTo(product.getMaxAmount()) == 0
                && version.getTerms().equals(product.getTerms())
                && version.getRepaymentModes().equals(product.getRepaymentModes())
                && version.getAnnualInterestRate().compareTo(product.getAnnualInterestRate()) == 0
                && version.isRequiresGuarantee() == product.isRequiresGuarantee();
    }

    // ------------------------------------------------------------------ 申请

    @Transactional
    public DrawdownOrder apply(String quoteNo, String payeeName, String payeeAccount, String purpose) {
        DrawdownQuote quote = quoteRepo.findById(quoteNo).orElseThrow();
        if (!quote.usable(Ids.now())) {
            throw new BizException(BizException.Code.QUOTE_EXPIRED);
        }
        ProductConfigVersion version = versionRepo.findById(quote.getProductVersionId()).orElseThrow();
        validateAmountAndTerm(version, quote.getAmount(), quote.getTermMonths(), quote.getRepaymentMode());
        // 报价到提交期间条件变化必须重新校验：按多层口径、以申请时点为准
        if (limitService.availableForDrawdown(quote.getCreditId(), version.getProductId(),
                version.isRequiresGuarantee()).compareTo(quote.getAmount()) < 0) {
            throw new BizException(BizException.Code.LIMIT_INSUFFICIENT);
        }

        DrawdownOrder order = new DrawdownOrder();
        order.setBizOrderNo(Ids.next("DD-"));
        order.setCreditId(quote.getCreditId());
        order.setQuoteNo(quoteNo);
        order.setProductId(quote.getProductId());
        order.setAmount(quote.getAmount());
        order.setPayeeName(payeeName);
        order.setPayeeAccount(payeeAccount);
        order.setPurpose(purpose);
        order.setStatus(DrawdownOrder.Status.PROCESSING);
        order.setPaymentStatus(DrawdownOrder.PaymentStatus.TO_SUBMIT);
        order.setBookingStatus(DrawdownOrder.BookingStatus.NONE);
        order.setBookingRetryCount(0);
        order.setCreatedAt(Ids.now());
        order.setUpdatedAt(Ids.now());
        orderRepo.save(order);

        quote.setStatus(DrawdownQuote.Status.USED);

        // 逐层预占额度 → 创建借据（Fineract 贷款账户）→ 提交付款
        limitService.preOccupy(quote.getCreditId(), order.getBizOrderNo(), version.getProductId(),
                version.isRequiresGuarantee(), quote.getAmount());
        String loanAccountNo = fineract.createLoan(version.getFineractProductId(), quote.getAmount(),
                quote.getTermMonths(), quote.getRepaymentMode(), quote.getFirstRepaymentDate());
        order.setLoanAccountNo(loanAccountNo);
        submitPayment(order);
        return order;
    }

    /** 提交付款；同步终态就地结算，受理中等待回调或查单。 */
    public void submitPayment(DrawdownOrder order) {
        try {
            SimulatorClient.PaymentSubmission sub = simulator.submitPayment(
                    order.getBizOrderNo(), order.getPayeeName(), order.getPayeeAccount(), order.getAmount());
            order.setExtSerialNo(sub.extSerialNo());
            order.setUpdatedAt(Ids.now());
            switch (sub.status()) {
                case "SUCCESS" -> onPaymentResult(order, "SUCCESS");
                case "REJECTED" -> onPaymentResult(order, "FAILED");
                default -> order.setPaymentStatus(DrawdownOrder.PaymentStatus.PROCESSING);
            }
        } catch (Exception e) {
            // 提交失败保留 TO_SUBMIT，由补偿任务重试（模拟服务按 bizOrderNo 幂等）
            log.warn("付款提交失败，等待补偿重试: {} {}", order.getBizOrderNo(), e.getMessage());
        }
    }

    // -------------------------------------------------- 外部结果确认（回调与查单共用）

    /**
     * 付款结果落业务单。幂等：业务单已终态、或该结果已生效时，直接确认不产生任何新记录。
     */
    @Transactional
    public void onPaymentResult(DrawdownOrder order, String result) {
        if (order.terminal()) {
            return; // 幂等：终态后收到的任何结果只影响外部流水，不改业务单
        }
        order.setUpdatedAt(Ids.now());
        if ("SUCCESS".equals(result)) {
            if (order.getPaymentStatus() == DrawdownOrder.PaymentStatus.SUCCESS) {
                return; // 幂等：成功已受理过
            }
            order.setPaymentStatus(DrawdownOrder.PaymentStatus.SUCCESS);
            order.setStatus(DrawdownOrder.Status.EXTERNAL_SUCCESS_BOOKING_PENDING);
            order.setBookingStatus(DrawdownOrder.BookingStatus.TO_BOOK);
            book(order); // 同步尝试入账；失败转 RETRY_NEEDED 由补偿任务继续
        } else {
            if (order.getPaymentStatus() == DrawdownOrder.PaymentStatus.FAILED) {
                return;
            }
            order.setPaymentStatus(DrawdownOrder.PaymentStatus.FAILED);
            order.setStatus(DrawdownOrder.Status.FAILED);
            limitService.releasePreOccupied(order.getCreditId(), order.getBizOrderNo(), order.getProductId(),
                    requiresGuarantee(order.getProductId()), order.getAmount());
        }
    }

    /**
     * 中台入账：调用 Fineract 放款登记 + 逐层预占转实占。
     * 幂等：入账前先查借据是否已 ACTIVE（重复回调/查单/重试不会重复放款）。
     */
    @Transactional
    public void book(DrawdownOrder order) {
        if (order.getBookingStatus() == DrawdownOrder.BookingStatus.BOOKED) {
            return;
        }
        try {
            if (fineract.isLoanActive(order.getLoanAccountNo())) {
                log.info("借据已生效，跳过重复放款登记: {}", order.getLoanAccountNo());
            } else {
                fineract.disburseLoan(order.getLoanAccountNo(), order.getAmount());
            }
            order.setBookingStatus(DrawdownOrder.BookingStatus.BOOKED);
            order.setBookedAmount(order.getAmount());
            order.setStatus(DrawdownOrder.Status.SUCCESS);
            order.setUpdatedAt(Ids.now());
            limitService.confirmOccupy(order.getCreditId(), order.getBizOrderNo(),
                    order.getLoanAccountNo(), order.getProductId(),
                    requiresGuarantee(order.getProductId()), order.getAmount());
        } catch (Exception e) {
            order.setBookingStatus(DrawdownOrder.BookingStatus.RETRY_NEEDED);
            order.setBookingRetryCount(order.getBookingRetryCount() + 1);
            order.setBookingLastError(e.getMessage());
            order.setUpdatedAt(Ids.now());
            log.warn("入账失败转补偿: {} retry={}", order.getBizOrderNo(), order.getBookingRetryCount());
        }
    }

    /** 查单收敛：补偿任务对 PROCESSING 超时的指令主动查单，结果走与回调相同的处理通道。 */
    @Transactional
    public void queryAndSettle(DrawdownOrder order) {
        SimulatorClient.ExternalStatus status = simulator.query("PAYMENT", order.getExtSerialNo());
        if ("SUCCESS".equals(status.status()) || "FAILED".equals(status.status())) {
            onPaymentResult(order, status.status());
        } else if ("RESULT_UNCONFIRMED".equals(status.status())) {
            order.setPaymentStatus(DrawdownOrder.PaymentStatus.RESULT_UNCONFIRMED);
        }
    }

    // ------------------------------------------------------------------ 查询

    public Map<String, Object> detail(String bizOrderNo) {
        DrawdownOrder order = orderRepo.findById(bizOrderNo).orElseThrow();
        return Map.of("bizOrderNo", order.getBizOrderNo(), "status", order.getStatus().name(),
                "amount", order.getAmount(),
                "payments", List.of(Map.of("extSerialNo", order.getExtSerialNo() == null ? "" : order.getExtSerialNo(),
                        "status", order.getPaymentStatus().name(), "amount", order.getAmount())),
                "booking", Map.of("status", order.getBookingStatus().name(),
                        "loanAccountNo", order.getLoanAccountNo() == null ? "" : order.getLoanAccountNo(),
                        "retryCount", order.getBookingRetryCount()));
    }

    private boolean requiresGuarantee(String productId) {
        return productRepo.findById(productId).map(ProductConfig::isRequiresGuarantee).orElse(false);
    }

    private void validateAmountAndTerm(ProductConfigVersion version, BigDecimal amount, Integer termMonths, String repaymentMode) {
        if (amount.compareTo(version.getMinAmount()) < 0 || amount.compareTo(version.getMaxAmount()) > 0) {
            throw new BizException(BizException.Code.PRODUCT_NOT_OPEN);
        }
        if (!version.termList().contains(termMonths)) {
            throw new BizException(BizException.Code.TERM_NOT_SUPPORTED);
        }
        if (!version.repaymentModeList().contains(repaymentMode)) {
            throw new BizException(BizException.Code.PRODUCT_NOT_OPEN);
        }
    }

    private ProductConfig product(String productId) {
        return productRepo.findById(productId).orElseThrow(() -> new BizException(BizException.Code.PRODUCT_NOT_OPEN));
    }

    private String writeJson(Object value) {
        try {
            return objectMapper.writeValueAsString(value);
        } catch (Exception e) {
            return "[]";
        }
    }
}

package com.rsd.middle.drawdown;

import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 提款业务单（阶段 2：单收款人，支付信息直接挂在本单上；阶段 4 多收款人引入 PaymentInstruction 子表，
 * 一个业务单对应多条支付指令、多个成功批次形成多笔借据）。
 * 状态机见 docs/接口契约-阶段2.md §2；"外部已付款成功、中台入账未完成"是显式可恢复状态。
 */
@Entity
@Table(name = "drawdown_order")
public class DrawdownOrder {

    public enum Status { PROCESSING, EXTERNAL_SUCCESS_BOOKING_PENDING, SUCCESS, FAILED, CANCELLED }

    /** 外部付款指令状态（本单一条指令）。 */
    public enum PaymentStatus { TO_SUBMIT, PROCESSING, SUCCESS, FAILED, RESULT_UNCONFIRMED }

    /** 中台入账（Fineract 放款登记）状态。 */
    public enum BookingStatus { NONE, TO_BOOK, BOOKED, RETRY_NEEDED }

    @Id
    private String bizOrderNo;
    private String creditId;
    private String quoteNo;
    private String productId;
    private BigDecimal amount;
    private String payeeName;
    private String payeeAccount;
    private String purpose;

    private Status status;
    private PaymentStatus paymentStatus;
    private String extSerialNo;
    private BookingStatus bookingStatus;
    private Integer bookingRetryCount;
    private String bookingLastError;
    private String loanAccountNo;       // Fineract 借据 id，创建成功即写入（放款前即存在）
    private BigDecimal bookedAmount;    // 实际入账金额
    private LocalDateTime createdAt;
    private LocalDateTime updatedAt;

    public boolean terminal() {
        return status == Status.SUCCESS || status == Status.FAILED || status == Status.CANCELLED;
    }

    public String getBizOrderNo() { return bizOrderNo; }
    public void setBizOrderNo(String bizOrderNo) { this.bizOrderNo = bizOrderNo; }
    public String getCreditId() { return creditId; }
    public void setCreditId(String creditId) { this.creditId = creditId; }
    public String getQuoteNo() { return quoteNo; }
    public void setQuoteNo(String quoteNo) { this.quoteNo = quoteNo; }
    public String getProductId() { return productId; }
    public void setProductId(String productId) { this.productId = productId; }
    public BigDecimal getAmount() { return amount; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public String getPayeeName() { return payeeName; }
    public void setPayeeName(String payeeName) { this.payeeName = payeeName; }
    public String getPayeeAccount() { return payeeAccount; }
    public void setPayeeAccount(String payeeAccount) { this.payeeAccount = payeeAccount; }
    public String getPurpose() { return purpose; }
    public void setPurpose(String purpose) { this.purpose = purpose; }
    public Status getStatus() { return status; }
    public void setStatus(Status status) { this.status = status; }
    public PaymentStatus getPaymentStatus() { return paymentStatus; }
    public void setPaymentStatus(PaymentStatus paymentStatus) { this.paymentStatus = paymentStatus; }
    public String getExtSerialNo() { return extSerialNo; }
    public void setExtSerialNo(String extSerialNo) { this.extSerialNo = extSerialNo; }
    public BookingStatus getBookingStatus() { return bookingStatus; }
    public void setBookingStatus(BookingStatus bookingStatus) { this.bookingStatus = bookingStatus; }
    public Integer getBookingRetryCount() { return bookingRetryCount; }
    public void setBookingRetryCount(Integer bookingRetryCount) { this.bookingRetryCount = bookingRetryCount; }
    public String getBookingLastError() { return bookingLastError; }
    public void setBookingLastError(String bookingLastError) { this.bookingLastError = bookingLastError; }
    public String getLoanAccountNo() { return loanAccountNo; }
    public void setLoanAccountNo(String loanAccountNo) { this.loanAccountNo = loanAccountNo; }
    public BigDecimal getBookedAmount() { return bookedAmount; }
    public void setBookedAmount(BigDecimal bookedAmount) { this.bookedAmount = bookedAmount; }
    public LocalDateTime getCreatedAt() { return createdAt; }
    public void setCreatedAt(LocalDateTime createdAt) { this.createdAt = createdAt; }
    public LocalDateTime getUpdatedAt() { return updatedAt; }
    public void setUpdatedAt(LocalDateTime updatedAt) { this.updatedAt = updatedAt; }
}

package com.rsd.channel;

import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDateTime;

/**
 * 渠道申请单：channelRefNo → bizOrderNo 的映射与展示状态就保存在渠道库。
 * 展示状态可以合并中台多个内部状态，但必须保留原始状态以便追踪（边界设计 §1）。
 */
@Entity
@Table(name = "channel_application")
public class ChannelApplicationRecord {

    public enum BizType { DRAWDOWN, REPAYMENT, CREDIT }

    @Id
    private String channelRefNo;
    private String channelId;
    private BizType bizType;
    private String bizOrderNo;         // 中台业务单号
    private String displayStatus;      // 对外展示状态（合并视图）
    private String middleRawStatus;    // 中台原始状态（追踪用）
    private String channelRuleSnapshotJson; // 申请时命中的渠道规则快照（阶段3：按快照核对争议）
    private LocalDateTime createdAt;
    private LocalDateTime updatedAt;

    public String getChannelRefNo() { return channelRefNo; }
    public void setChannelRefNo(String channelRefNo) { this.channelRefNo = channelRefNo; }
    public String getChannelId() { return channelId; }
    public void setChannelId(String channelId) { this.channelId = channelId; }
    public BizType getBizType() { return bizType; }
    public void setBizType(BizType bizType) { this.bizType = bizType; }
    public String getBizOrderNo() { return bizOrderNo; }
    public void setBizOrderNo(String bizOrderNo) { this.bizOrderNo = bizOrderNo; }
    public String getDisplayStatus() { return displayStatus; }
    public void setDisplayStatus(String displayStatus) { this.displayStatus = displayStatus; }
    public String getMiddleRawStatus() { return middleRawStatus; }
    public void setMiddleRawStatus(String middleRawStatus) { this.middleRawStatus = middleRawStatus; }
    public String getChannelRuleSnapshotJson() { return channelRuleSnapshotJson; }
    public void setChannelRuleSnapshotJson(String channelRuleSnapshotJson) { this.channelRuleSnapshotJson = channelRuleSnapshotJson; }
    public LocalDateTime getCreatedAt() { return createdAt; }
    public void setCreatedAt(LocalDateTime createdAt) { this.createdAt = createdAt; }
    public LocalDateTime getUpdatedAt() { return updatedAt; }
    public void setUpdatedAt(LocalDateTime updatedAt) { this.updatedAt = updatedAt; }
}

package com.rsd.channel;

import com.rsd.channel.ChannelApplicationRecord.BizType;
import com.rsd.channel.ChannelProductRule;
import com.rsd.channel.ChannelProductRuleRepository;
import com.rsd.channel.ChannelApplicationRecordRepository;
import com.rsd.channel.MiddleClient;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ThreadLocalRandom;

/**
 * 渠道业务服务：开放条件过滤、字段转换、申请入口、展示状态聚合。
 * 渠道规则（主设计 §四）：企业自助渠道单笔上限 30 万、期限 3/6/12；客户经理渠道上限 100 万、期限同中台。
 * "同一客户换个入口，可选条件不同"由本服务与中台配置差异复现。
 */
@Service
public class ChannelService {

    private final ChannelProductRuleRepository ruleRepo;
    private final ChannelApplicationRecordRepository recordRepo;
    private final MiddleClient middle;

    public ChannelService(ChannelProductRuleRepository ruleRepo, ChannelApplicationRecordRepository recordRepo,
                          MiddleClient middle) {
        this.ruleRepo = ruleRepo;
        this.recordRepo = recordRepo;
        this.middle = middle;
    }

    /** 可选条件：先取中台产品能力，再按渠道规则收窄（金额上限、期限、开放开关）。 */
    @SuppressWarnings("unchecked")
    public Map<String, Object> options(String channelId, String creditId) {
        Map<String, Object> middleOptions = middle.drawdownOptions(creditId);
        List<Map<String, Object>> products = ((List<Object>) middleOptions.get("products")).stream()
                .map(item -> (Map<String, Object>) item)
                .map(p -> narrowByChannel(channelId, p))
                .filter(p -> p != null)
                .toList();
        return Map.of("channelId", channelId, "creditId", creditId, "products", products);
    }

    @SuppressWarnings("unchecked")
    private Map<String, Object> narrowByChannel(String channelId, Map<String, Object> product) {
        return ruleRepo.findByChannelId(channelId).stream()
                .filter(rule -> rule.isEnabled() && rule.getProductId().equals(product.get("productId")))
                .findFirst()
                .map(rule -> {
                    BigDecimal capped = ((BigDecimal) product.get("maxAmount")).min(rule.getMaxAmount());
                    List<Integer> terms = ((List<Integer>) product.get("terms")).stream()
                            .filter(t -> rule.termList().contains(t))
                            .toList();
                    if (terms.isEmpty() || capped.compareTo((BigDecimal) product.get("minAmount")) < 0) {
                        return null; // 渠道开放范围收窄到不可用时直接不透出
                    }
                    return Map.<String, Object>of(
                            "productId", product.get("productId"),
                            "productName", product.get("productName"),
                            "minAmount", product.get("minAmount"),
                            "maxAmount", capped,
                            "terms", terms,
                            "repaymentModes", product.get("repaymentModes"),
                            "availableAmount", product.get("availableAmount"),
                            "channelMaxAmount", rule.getMaxAmount());
                })
                .orElse(null);
    }

    /** 提款申请入口：渠道校验自己的开放规则（金额、期限），转换字段后调用中台。 */
    @SuppressWarnings("unchecked")
    public Map<String, Object> applyDrawdown(String channelId, Map<String, Object> request) {
        String creditId = String.valueOf(request.get("creditId"));
        String productId = String.valueOf(request.get("productId"));
        BigDecimal amount = new BigDecimal(String.valueOf(request.get("amount")));
        int termMonths = Integer.parseInt(String.valueOf(request.get("termMonths")));

        ChannelProductRule rule = ruleRepo.findByChannelId(channelId).stream()
                .filter(r -> r.getProductId().equals(productId) && r.isEnabled())
                .findFirst()
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "PRODUCT_NOT_OPEN"));
        if (amount.compareTo(rule.getMaxAmount()) > 0) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "CHANNEL_AMOUNT_LIMIT");
        }
        if (!rule.termList().contains(termMonths)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "CHANNEL_TERM_LIMIT");
        }

        // 字段转换：渠道语义 → 中台契约（quote → apply 两步，均按 docs/接口契约-阶段2.md）
        Map<String, Object> quote = middle.quote(Map.of(
                "creditId", creditId,
                "productId", productId,
                "amount", amount,
                "termMonths", termMonths,
                "repaymentMode", String.valueOf(request.get("repaymentMode")),
                "firstRepaymentDate", String.valueOf(request.getOrDefault("firstRepaymentDate", ""))));
        Map<String, Object> applied = middle.applyDrawdown(String.valueOf(quote.get("quoteNo")),
                String.valueOf(request.get("payeeName")),
                String.valueOf(request.get("payeeAccount")),
                String.valueOf(request.getOrDefault("purpose", "")));

        String channelRefNo = nextRef();
        saveRecord(channelRefNo, channelId, BizType.DRAWDOWN, String.valueOf(applied.get("bizOrderNo")),
                displayOf(String.valueOf(applied.get("status"))));
        return Map.of("channelRefNo", channelRefNo, "displayStatus", "PROCESSING");
    }

    public Map<String, Object> applyRepayment(String channelId, Map<String, Object> request) {
        Map<String, Object> applied = middle.applyRepayment(
                String.valueOf(request.get("loanAccountNo")),
                String.valueOf(request.get("payerAccount")),
                String.valueOf(request.get("type")),
                new BigDecimal(String.valueOf(request.get("amount"))));
        String channelRefNo = nextRef();
        saveRecord(channelRefNo, channelId, BizType.REPAYMENT, String.valueOf(applied.get("bizOrderNo")),
                displayOf(String.valueOf(applied.get("status"))));
        return Map.of("channelRefNo", channelRefNo, "displayStatus", "PROCESSING");
    }

    /** 结果查询：取中台原始状态，按映射合并为展示状态，同时保存原始状态供追踪。 */
    @SuppressWarnings("unchecked")
    public Map<String, Object> drawdownDetail(String channelRefNo) {
        ChannelApplicationRecord record = requireRecord(channelRefNo, BizType.DRAWDOWN);
        Map<String, Object> middleDetail = middle.drawdownDetail(record.getBizOrderNo());
        String display = displayOf(String.valueOf(middleDetail.get("status")));
        record.setDisplayStatus(display);
        record.setMiddleRawStatus(String.valueOf(middleDetail.get("status")));
        record.setUpdatedAt(LocalDateTime.now().withNano(0));
        recordRepo.save(record);
        return Map.of("channelRefNo", channelRefNo, "displayStatus", display,
                "middleStatus", middleDetail.get("status"), "detail", middleDetail);
    }

    /**
     * 授信申请入口（阶段 3）：渠道做准入（允许发起授信申请的渠道），透传到中台走外部审批。
     * 申请单同时保存渠道侧快照，便于追溯当时从哪个渠道、以什么条件发起。
     */
    public Map<String, Object> applyCredit(String channelId, Map<String, Object> request) {
        if (!channelAllowsCredit(channelId)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "CHANNEL_CREDIT_NOT_OPEN");
        }
        Map<String, Object> applied = middle.applyCredit(request);
        String channelRefNo = nextRef();
        ChannelApplicationRecord record = new ChannelApplicationRecord();
        record.setChannelRefNo(channelRefNo);
        record.setChannelId(channelId);
        record.setBizType(BizType.CREDIT);
        record.setBizOrderNo(String.valueOf(applied.get("bizOrderNo")));
        record.setDisplayStatus("PROCESSING");
        record.setChannelRuleSnapshotJson("{\"channelId\":\"" + channelId + "\",\"entry\":\"credit-application\"}");
        record.setCreatedAt(LocalDateTime.now().withNano(0));
        record.setUpdatedAt(record.getCreatedAt());
        recordRepo.save(record);
        return Map.of("channelRefNo", channelRefNo,
                "bizOrderNo", applied.get("bizOrderNo"),
                "displayStatus", "PROCESSING");
    }

    public Map<String, Object> creditApplicationDetail(String channelRefNo) {
        ChannelApplicationRecord record = recordRepo.findById(channelRefNo)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "APPLICATION_NOT_FOUND"));
        Map<String, Object> middleDetail = middle.creditApplicationDetail(record.getBizOrderNo());
        String display = "APPROVED".equals(String.valueOf(middleDetail.get("status"))) ? "SUCCESS"
                : "REJECTED".equals(String.valueOf(middleDetail.get("status"))) ? "FAILED" : "PROCESSING";
        record.setDisplayStatus(display);
        record.setMiddleRawStatus(String.valueOf(middleDetail.get("status")));
        record.setUpdatedAt(LocalDateTime.now().withNano(0));
        recordRepo.save(record);
        return Map.of("channelRefNo", channelRefNo, "displayStatus", display, "detail", middleDetail);
    }

    /** 渠道准入：阶段 3 两个渠道均允许发起授信申请；规则集中在此便于后续按渠道差异调整。 */
    private boolean channelAllowsCredit(String channelId) {
        return "SELF_SERVICE".equals(channelId) || "RM_ASSISTED".equals(channelId);
    }

    @SuppressWarnings("unchecked")
    public Map<String, Object> repaymentDetail(String channelRefNo) {
        ChannelApplicationRecord record = requireRecord(channelRefNo, BizType.REPAYMENT);
        Map<String, Object> middleDetail = middle.repaymentDetail(record.getBizOrderNo());
        String display = displayOf(String.valueOf(middleDetail.get("status")));
        record.setDisplayStatus(display);
        record.setMiddleRawStatus(String.valueOf(middleDetail.get("status")));
        record.setUpdatedAt(LocalDateTime.now().withNano(0));
        recordRepo.save(record);
        return Map.of("channelRefNo", channelRefNo, "displayStatus", display, "detail", middleDetail);
    }

    /**
     * 展示状态映射（契约 §2）：中台 PROCESSING / EXTERNAL_SUCCESS_BOOKING_PENDING 等处理中状态
     * 对外统一展示"PROCESSING"；成功与失败直传。映射关系保留在 record.middleRawStatus。
     */
    private String displayOf(String middleStatus) {
        return switch (middleStatus) {
            case "SUCCESS", "FAILED" -> middleStatus;
            default -> "PROCESSING"; // PROCESSING / EXTERNAL_SUCCESS_BOOKING_PENDING / 其他处理中状态
        };
    }

    private void saveRecord(String channelRefNo, String channelId, BizType type, String bizOrderNo, String display) {
        ChannelApplicationRecord record = new ChannelApplicationRecord();
        record.setChannelRefNo(channelRefNo);
        record.setChannelId(channelId);
        record.setBizType(type);
        record.setBizOrderNo(bizOrderNo);
        record.setDisplayStatus(display);
        record.setCreatedAt(LocalDateTime.now().withNano(0));
        record.setUpdatedAt(record.getCreatedAt());
        recordRepo.save(record);
    }

    private ChannelApplicationRecord requireRecord(String channelRefNo, BizType type) {
        return recordRepo.findById(channelRefNo)
                .filter(record -> record.getBizType() == type)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "APPLICATION_NOT_FOUND"));
    }

    private String nextRef() {
        return "CHN-%06d".formatted(ThreadLocalRandom.current().nextInt(1000000));
    }
}

package com.rsd.middle.external;

import com.rsd.middle.common.BizException;
import com.rsd.middle.credit.CreditApplicationOrder;
import com.rsd.middle.credit.CreditApplicationRepository;
import com.rsd.middle.credit.CreditService;
import com.rsd.middle.drawdown.DrawdownOrder;
import com.rsd.middle.drawdown.DrawdownOrderRepository;
import com.rsd.middle.drawdown.DrawdownService;
import com.rsd.middle.repay.RepaymentOrder;
import com.rsd.middle.repay.RepaymentOrderRepository;
import com.rsd.middle.repay.RepaymentService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import java.math.BigDecimal;
import java.util.Map;

/**
 * 外部结果回调接收（模拟服务 → 中台）：付款、扣款、授信审批。
 * 幂等由各业务服务保证：终态业务单收到重复回调直接确认（DUPLICATE_CALLBACK 不改变状态）。
 * 回调成功只代表外部环节完成；提款是否成功以中台入账状态为准，授信是否生效以中台账本为准。
 */
@RestController
@RequestMapping("/middle/api/v1/callbacks")
public class ExternalResultController {

    private static final Logger log = LoggerFactory.getLogger(ExternalResultController.class);

    private final DrawdownOrderRepository drawdownRepo;
    private final RepaymentOrderRepository repayRepo;
    private final CreditApplicationRepository creditRepo;
    private final DrawdownService drawdownService;
    private final RepaymentService repaymentService;
    private final CreditService creditService;

    public ExternalResultController(DrawdownOrderRepository drawdownRepo, RepaymentOrderRepository repayRepo,
                                    CreditApplicationRepository creditRepo, DrawdownService drawdownService,
                                    RepaymentService repaymentService, CreditService creditService) {
        this.drawdownRepo = drawdownRepo;
        this.repayRepo = repayRepo;
        this.creditRepo = creditRepo;
        this.drawdownService = drawdownService;
        this.repaymentService = repaymentService;
        this.creditService = creditService;
    }

    public record ExternalResult(String type, String extSerialNo, String bizOrderNo, String result,
                                 BigDecimal approvedLimit, String finishedAt) {
    }

    @PostMapping("/external-result")
    public Map<String, Object> onExternalResult(@RequestBody ExternalResult callback) {
        log.info("收到外部结果回调: {}", callback);
        try {
            switch (callback.type()) {
                case "PAYMENT" -> {
                    DrawdownOrder order = drawdownRepo.findById(callback.bizOrderNo()).orElse(null);
                    if (order != null && callback.extSerialNo().equals(order.getExtSerialNo())) {
                        drawdownService.onPaymentResult(order, callback.result());
                    }
                }
                case "DEDUCTION" -> {
                    RepaymentOrder order = repayRepo.findById(callback.bizOrderNo()).orElse(null);
                    if (order != null && callback.extSerialNo().equals(order.getExtSerialNo())) {
                        repaymentService.onDeductionResult(order, callback.result());
                    }
                }
                case "APPROVAL" -> {
                    CreditApplicationOrder order = creditRepo.findById(callback.bizOrderNo()).orElse(null);
                    if (order != null && callback.extSerialNo().equals(order.getApprovalExtSerialNo())) {
                        creditService.onApprovalResult(order, callback.result(), callback.approvedLimit());
                    }
                }
                default -> log.warn("未知回调类型: {}", callback.type());
            }
        } catch (BizException e) {
            if (e.code != BizException.Code.DUPLICATE_CALLBACK) {
                throw e;
            }
        }
        return Map.of("received", true);
    }
}

package com.rsd.middle.drawdown;

import com.rsd.middle.credit.CreditLimitRepository;
import com.rsd.middle.credit.LimitService;
import com.rsd.middle.credit.ProductConfigRepository;
import com.rsd.middle.credit.ProductConfig;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import java.math.BigDecimal;
import java.util.List;
import java.util.Map;

/** 中台渠道接入 API（阶段 2 提款部分）。契约见 docs/接口契约-阶段2.md §4。 */
@RestController
@RequestMapping("/middle/api/v1/drawdowns")
public class DrawdownController {

    private final DrawdownService drawdownService;
    private final LimitService limitService;
    private final ProductConfigRepository productRepo;
    private final CreditLimitRepository creditRepo;

    public DrawdownController(DrawdownService drawdownService, LimitService limitService,
                              ProductConfigRepository productRepo, CreditLimitRepository creditRepo) {
        this.drawdownService = drawdownService;
        this.limitService = limitService;
        this.productRepo = productRepo;
        this.creditRepo = creditRepo;
    }

    public record QuoteRequest(String creditId, String productId, BigDecimal amount,
                               Integer termMonths, String repaymentMode, String firstRepaymentDate) {
    }

    public record ApplyRequest(String quoteNo, String payeeName, String payeeAccount, String purpose) {
    }

    @GetMapping("/options")
    public Map<String, Object> options(@RequestParam String creditId) {
        limitService.get(creditId);
        List<Map<String, Object>> products = productRepo.findAll().stream()
                .map(p -> Map.<String, Object>of(
                        "productId", p.getProductId(),
                        "productName", p.getProductName(),
                        "minAmount", p.getMinAmount(),
                        "maxAmount", p.getMaxAmount(),
                        "terms", p.termList(),
                        "repaymentModes", p.repaymentModeList(),
                        // 多层口径：各约束层余量取最小值（总授信/产品子额度/集团限额/担保覆盖）
                        "availableAmount", limitService.availableForDrawdown(creditId, p.getProductId(), p.isRequiresGuarantee())))
                .toList();
        return Map.of("creditId", creditId, "products", products);
    }

    @PostMapping("/quote")
    public Map<String, Object> quote(@RequestBody QuoteRequest request) {
        return drawdownService.quote(request.creditId(), request.productId(), request.amount(),
                request.termMonths(), request.repaymentMode(), request.firstRepaymentDate());
    }

    @PostMapping
    public Map<String, Object> apply(@RequestBody ApplyRequest request) {
        DrawdownOrder order = drawdownService.apply(request.quoteNo(), request.payeeName(),
                request.payeeAccount(), request.purpose());
        return Map.of("bizOrderNo", order.getBizOrderNo(), "status", order.getStatus().name());
    }

    @GetMapping("/{bizOrderNo}")
    public Map<String, Object> detail(@PathVariable String bizOrderNo) {
        return drawdownService.detail(bizOrderNo);
    }
}

